from collections import deque


def bfs(graph, start):
    found = {start}
    queue = deque([start])
    order = []
    while queue:
        v = queue.popleft()
        order.append(v)
        for n in sorted(graph.adjacency[v]):
            if n not in found:
                found.add(n)
                queue.append(n)
        if not queue:
            for u in sorted(graph.adjacency):
                if u not in found:
                    found.add(u)
                    queue.append(u)
                    break
    return order
